// Это файл для объявления типов, которые могут быть использованы в TypeScript проекте

// Объявление для импорта изображений
declare module '*.png';
declare module '*.jpg';
declare module '*.jpeg';
declare module '*.gif';
declare module '*.svg';
declare module '*.webp';

// Объявление для импорта стилей
declare module '*.css';
declare module '*.scss';
declare module '*.sass';

// Другие типы статических файлов
declare module '*.json'; 